// File: frontend/src/context/AuthContext.js

import React, { createContext, useState, useContext, useEffect } from 'react';
import axios from 'axios';

// 1. Create the context
const AuthContext = createContext(null);

// 2. Create the provider component (There should only be ONE of these)
export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    const loadUser = async () => {
        // Get token from local storage
        const token = localStorage.getItem('token');
        
        if (token) {
            // Set the token in axios default headers
            axios.defaults.headers.common['x-auth-token'] = token;
            try {
                // Fetch user data from the protected backend route
                const res = await axios.get('/api/auth');
                setUser(res.data); // Set user state with the response data
            } catch (err) {
                console.error('Token is not valid, removing it.', err);
                localStorage.removeItem('token'); // Remove invalid token
            }
        }
        setLoading(false);
    };

    // This effect runs once when the component mounts to load the user
    useEffect(() => {
        loadUser();
    }, []);

    // Login function
    const login = async (email, password) => {
        try {
            const res = await axios.post('/api/auth/login', { email, password });
            localStorage.setItem('token', res.data.token);
            await loadUser(); // Load user data immediately after successful login
        } catch (error) {
            // Re-throw the error so the component can catch it and display a message
            throw error;
        }
    };

    // Logout function
    const logout = () => {
        localStorage.removeItem('token');
        delete axios.defaults.headers.common['x-auth-token'];
        setUser(null);
    };

    // The value provided to all children components
    const authContextValue = {
        user,
        login,
        logout,
        isAuthenticated: !!user, // Will be true if the user object is not null
        loading,
    };

    return (
        <AuthContext.Provider value={authContextValue}>
            {/* Render children only when not loading */}
            {!loading && children}
        </AuthContext.Provider>
    );
};

// 3. Create a custom hook to easily use the context in other components
export const useAuth = () => {
    return useContext(AuthContext);
};
